-- docs/superpowers/plans/2026-11-18-permissions-server-enforcement.md Task 6.
--
-- Replaces the DELETE RLS policies on orders, customers, and
-- inventory_items with permission-key checks via app_has_permission()
-- (Task 1), instead of a bare tenant_id check (orders, inventory_items --
-- both generated by the generic tenant_tables loop in
-- 20240601000000_track_base_schema.sql, which only ever checked
-- tenant_id = app_current_tenant_id() with no role/permission predicate)
-- or a hard-coded role list (customers, from
-- 20260917150000_customers_delete_role_guard.sql: owner/admin/manager/
-- branch_manager). All three now key off the app's own permission matrix
-- (orders.delete / customers.delete / inventory.delete) via
-- app_default_permission()/the tenant's custom roles.permissions JSONB/
-- per-staff overrides, the same resolution already wired into the RPCs in
-- Tasks 2-5, instead of a fixed role enum that drifts from the client-side
-- DEFAULT_ROLES in permissionService.ts.
--
-- orders_tenant_delete: previously
--   app_is_super_admin() OR tenant_id = app_current_tenant_id()
-- customers_tenant_delete: previously
--   app_is_super_admin() OR (tenant_id = app_current_tenant_id() AND
--     staff.role IN ('owner','admin','manager','branch_manager'))
-- inventory_items_tenant_delete: previously
--   app_is_super_admin() OR tenant_id = app_current_tenant_id()
-- (the generic %I_tenant_delete form from the tenant_tables loop, never
-- overridden for this table before now).

DROP POLICY IF EXISTS orders_tenant_delete ON orders;
CREATE POLICY orders_tenant_delete ON orders
    FOR DELETE USING (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND app_has_permission('orders.delete')
        )
    );

DROP POLICY IF EXISTS customers_tenant_delete ON customers;
CREATE POLICY customers_tenant_delete ON customers
    FOR DELETE USING (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND app_has_permission('customers.delete')
        )
    );

DROP POLICY IF EXISTS inventory_items_tenant_delete ON inventory_items;
CREATE POLICY inventory_items_tenant_delete ON inventory_items
    FOR DELETE USING (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND app_has_permission('inventory.delete')
        )
    );
